	/**
	 * Default Constructor
	 */
    public ClaimService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ClaimEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ClaimRepository.class) );
		this.validator		= applicationContext.getBean(ClaimValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Claim
	 */
		public Claim createClaim( CreateClaimCommand command ) {

		Claim entity = new Claim();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setClaimId( command.getClaimId() );
            entity.setClaimNumber( command.getClaimNumber() );
            entity.setTotalAmount( command.getTotalAmount() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Claim {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateClaimCommand
	 * @return		Claim
	 */
	public Claim updateClaim( UpdateClaimCommand command ) {

		Claim entity = new Claim();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setClaimId( command.getClaimId() );
            entity.setClaimNumber( command.getClaimNumber() );
            entity.setTotalAmount( command.getTotalAmount() );
            entity.setPatient( command.getPatient() );
            entity.setCoverage( command.getCoverage() );
            entity.setEncounter( command.getEncounter() );
            entity.setInvoices( command.getInvoices() );
            entity.setPayer( command.getPayer() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Claim {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteClaimCommand
	 */
	public void delete( DeleteClaimCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getClaimId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Claim {0} ", id );

	}

	/**
	 * Method to retrieve the Claim via ClaimFetchOneSummary
	 * @param 	summary ClaimFetchOneSummary
	 * @return 	ClaimFetchOneResponse
	 */
	public Claim getClaim( ClaimFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ClaimFetchOneSummary arg cannot be null" );

		Claim entity = null;
		UUID id = summary.getClaimId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Claim using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Claims
	 *
	 * @return 	List<Claim>
	 */
    public List<Claim> getAllClaim() {
		List<Claim> list = projector.findAll( new FindAllClaimQuery() );
		return list;
	}

	/**
	 * assign Patient on Claim
	 * @param		command AssignPatientToClaimCommand
	 */
	public void assignPatient( AssignPatientToClaimCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignPatient(command.getClaimId(), command.getAssignment());

	}

